import numpy as np


def mesh_rettangolo(Lx, Ly, nx, ny):
    x, y = np.meshgrid(np.linspace(0, Lx, nx + 1), np.linspace(0, Ly, ny + 1))
    nodi = np.column_stack([x.ravel(), y.ravel()])
    tri = []
    for j in range(ny):
        for i in range(nx):
            a = j * (nx + 1) + i
            b, c, d = a + 1, a + nx + 2, a + nx + 1
            tri += [(a, b, c), (a, c, d)]
    return nodi, np.array(tri)
